usage:
import { AiMessageActions } from "@/components/design-for-ai/ai-message-actions";

<AiMessageActions
  author="Wren"
  versions={[{ id: "a1", meta: "Wren 2 · 3.2s", paragraphs: [answer] }]}
  onRegenerate={async () => {
    const text = await regenerate(messageId); // your streaming call, awaited
    return { id: crypto.randomUUID(), meta: "Wren 2", paragraphs: text.split("\n\n") };
  }}
  onFeedback={({ versionId, value, reasons, note }) => track("rating", { versionId, value, reasons, note })}
/>

// The reason popover is positioned inside the component (no portal). If the reply sits in a
// scroll container that clips, give the container room above the row or lift the popover
// into a portal on document.body.
